import React, { useState } from 'react';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import styles from './ProductCard.module.css';

// Product-specific emoji images
const PRODUCT_IMAGES = {
  // Meat & Fish
  'dhoopudu mutton': '🥩', 'mutton': '🥩', 'goat': '🐐',
  'dam fish': '🐟', 'fish': '🐟',
  'kadaknath chicken': '🐓', 'chicken': '🍗',
  'mekapothu': '🐐',
  // Vegetables
  'carrot': '🥕', 'brinjal': '🍆', 'tomato': '🍅',
  'lemon': '🍋', 'lady finger': '🫘', 'okra': '🫘',
  'beetroot': '🫚', 'onion': '🧅', 'ginger': '🫚',
  'coriander': '🌿', 'capsicum': '🫑', 'cabbage': '🥬',
  'sweet corn': '🌽', 'corn': '🌽', 'amla': '🍈',
  // Dairy
  'egg': '🥚', 'cow milk': '🥛', 'buffalo milk': '🫙',
  'milk': '🥛',
  // Organic
  'ghee': '🫙', 'sesame oil': '🫙', 'groundnut oil': '🫙',
  'coconut oil': '🫙', 'honey': '🍯', 'oil': '🫙',
  // Millets
  'ragi': '🌾', 'dosa mix': '🫓', 'jowar': '🌾',
  'brown sugar': '🍯', 'rock salt': '🧂', 'salt': '🧂',
  // Masalas
  'mutton masala': '🌶️', 'chicken masala': '🌶️', 'masala': '🌶️',
  // Dry Fruits
  'almond': '🥜', 'cashew': '🥜', 'pistachio': '🥜',
  'walnut': '🥜', 'dry grapes': '🍇', 'raisins': '🍇',
  'anjeer': '🍑', 'dry mango': '🥭', 'dry kiwi': '🥝',
  // Chocolates
  'milk chocolate': '🍫', 'dark chocolate': '🍫', 'chocolate': '🍫',
};

const CATEGORY_FALLBACK = {
  'meat-fish': '🥩', 'vegetables': '🥦', 'dairy-eggs': '🥛',
  'oils-ghee': '🫙', 'millets-groceries': '🌾', 'dry-fruits': '🥜',
  'masalas': '🌶️', 'chocolates': '🍫',
};

const CATEGORY_COLORS = {
  'meat-fish': { bg: '#fff1f2', border: '#fda4af' },
  'vegetables': { bg: '#f0fdf4', border: '#86efac' },
  'dairy-eggs': { bg: '#eff6ff', border: '#93c5fd' },
  'oils-ghee': { bg: '#fefce8', border: '#fde047' },
  'millets-groceries': { bg: '#fff7ed', border: '#fdba74' },
  'dry-fruits': { bg: '#fdf4ff', border: '#d8b4fe' },
  'masalas': { bg: '#fff1f2', border: '#fca5a5' },
  'chocolates': { bg: '#fef3c7', border: '#fbbf24' },
};

const getProductEmoji = (name, category) => {
  const lower = name.toLowerCase();
  for (const [key, emoji] of Object.entries(PRODUCT_IMAGES)) {
    if (lower.includes(key)) return emoji;
  }
  return CATEGORY_FALLBACK[category] || '🛒';
};

const ProductCard = ({ product }) => {
  const { addToCart } = useCart();
  const { toggleWishlist, isWishlisted } = useWishlist();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [qty, setQty] = useState(1);
  const [adding, setAdding] = useState(false);

  const wishlisted = isWishlisted(product._id);
  const emoji = getProductEmoji(product.name, product.category);
  const colors = CATEGORY_COLORS[product.category] || { bg: '#f9fafb', border: '#e5e7eb' };
  const discount = product.originalPrice > product.price
    ? Math.round((1 - product.price / product.originalPrice) * 100) : 0;

  const handleAddToCart = () => {
    if (!user) {
      toast('Please login to add items to cart 👤', { icon: '🔑' });
      navigate('/login', { state: { from: '/shop' } });
      return;
    }
    setAdding(true);
    addToCart(product, qty);
    toast.success(`Added to cart! 🛒`, { duration: 1500 });
    setQty(1);
    setTimeout(() => setAdding(false), 600);
  };

  const handleWishlist = async () => {
    if (!user) { toast('Login to save wishlist', { icon: '🔑' }); return; }
    await toggleWishlist(product._id);
  };

  return (
    <div className={styles.card}>
      {/* Image */}
      <div className={styles.imageWrap} style={{ background: `linear-gradient(135deg, ${colors.bg}, white)`, borderBottom: `2px solid ${colors.border}` }}>
        {product.image ? (
          <img src={product.image} alt={product.name} className={styles.image} />
        ) : (
          <div className={styles.emojiImg}>{emoji}</div>
        )}
        {!product.inStock && (
          <div className={styles.outOverlay}>Out of Stock</div>
        )}
        {discount > 0 && product.inStock && (
          <span className={styles.discountBadge}>{discount}% OFF</span>
        )}
        {product.featured && product.inStock && (
          <span className={styles.featuredBadge}>⭐</span>
        )}
        <button
          className={`${styles.wishBtn} ${wishlisted ? styles.wishlisted : ''}`}
          onClick={handleWishlist}
        >
          {wishlisted ? '❤️' : '🤍'}
        </button>
      </div>

      {/* Body */}
      <div className={styles.body}>
        <div className={styles.catLabel}>{product.category.replace('-', ' ')}</div>
        <h3 className={styles.name}>{product.name}</h3>
        {product.description && <p className={styles.desc}>{product.description}</p>}

        <div style={{ display: 'flex', alignItems: 'center', gap: 6, margin: '6px 0' }}>
          <span className={styles.unit}>{product.unit}</span>
          {product.inStock
            ? <span style={{ fontSize: 11, color: '#16a34a', fontWeight: 700 }}>✓ In Stock</span>
            : <span style={{ fontSize: 11, color: '#dc2626', fontWeight: 700 }}>✗ Out of Stock</span>
          }
        </div>

        <div className={styles.priceRow}>
          <span className={styles.price}>₹{product.price}</span>
          {product.originalPrice > product.price && (
            <span className={styles.oldPrice}>₹{product.originalPrice}</span>
          )}
        </div>

        {product.inStock ? (
          <div className={styles.actions}>
            <div className={styles.qtyBox}>
              <button onClick={() => setQty(q => Math.max(1, q - 1))} className={styles.qBtn}>−</button>
              <span className={styles.qVal}>{qty}</span>
              <button onClick={() => setQty(q => Math.min(20, q + 1))} className={styles.qBtn}>+</button>
            </div>
            <button
              className={`${styles.addBtn} ${adding ? styles.added : ''}`}
              onClick={handleAddToCart}
              disabled={adding}
            >
              {adding ? '✓ Added!' : '+ Add'}
            </button>
          </div>
        ) : (
          <div className={styles.outBtn}>Notify Me</div>
        )}
      </div>
    </div>
  );
};

export default ProductCard;
